head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > defaultShowHeaderFilter]<br/>GridView 컴포넌트 렌더링 시 HeaderFilter 를 표시할지 설정합니다.",
    "validation" : [
        "headerFilter=true 인 경우에만 동작합니다.",
        "true 설정 시, GridView 컴포넌트 렌더링 시 HeaderFilter 를 표시합니다.",
        "true 설정 시, headerFilter=false 이면 항상 false 로 동작합니다.",
        "false 설정 시, GridView 컴포넌트 렌더링 시 HeaderFilter 를 표시하지 않습니다.",
        "미설정 시, GridView 컴포넌트 렌더링 시 HeaderFilter 를 표시하지 않습니다.",
        "HeaderFilter 기능은 동적으로 생성이 불가능하며 렌더링 시 생성 여부를 결정한 후 표시 여부만 동적으로 처리합니다.",
        "headerFilter=false 이면 HeaderFilter 기능이 생성되지 않아 defaultShowHeaderFilter 속성 및 showHeaderFilter() 메소드가 동작하지 않습니다.",
        "mergeCells 속성에 의해 Body Cell 이 병합된 경우 defaultShowHeaderFilter=false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 미적용 → onpageload setValue (mergeCells 콤보 기본값)
    con_mergeCells.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (con 값은 headerFilter 처럼 렌더 시 결정되는 속성이므로 Target 재생성 버튼으로 재렌더)
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 값 조회
    let vHeaderFilter = con_headerFilter.getText();           // '' 미설정 / 'true' / 'false'
    let vDefaultShow  = con_defaultShowHeaderFilter.getText(); // '' 미설정 / 'true' / 'false'
    let vMergeCells   = con_mergeCells.getValue();             // '' 미설정 / 'bycol'

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblHf = (vHeaderFilter === '' ? '(미설정=기본 false)' : vHeaderFilter);
    let lblDs = (vDefaultShow === '' ? '(미설정=기본 false)' : vDefaultShow);
    let lblMc = (vMergeCells === '' ? '(미설정)' : vMergeCells);
    $c.gcm.createLabel('label="[전제] headerFilter=' + lblHf + ' / defaultShowHeaderFilter=' + lblDs + ' / mergeCells=' + lblMc + ' 로 그리드 생성\n[절차] con 값 변경 후 Target 재생성 -> 필터행 표시 확인 버튼 클릭\n[확인] headerFilter=true + defaultShowHeaderFilter=true 면 필터행 표시 / false 또는 미설정이면 숨김 / headerFilter=false 또는 미설정이면 HeaderFilter 기능 자체가 생성되지 않아 필터행 미생성\n[참고] mergeCells=bycol 로 Body Cell 병합 시 가이드상 defaultShowHeaderFilter=false 로 동작(필터행 숨김) 이나, 현 배포 엔진은 억제 로직 미탑재로 필터행이 계속 표시됨(엔진 미구현 한계)"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // mergeCells=bycol 케이스 : col1 에 세로 인접 동일 값(A,A,B,B) 을 넣어 실제 병합(td rowspan) 발생시킴
    if (vMergeCells === 'bycol') {
        dlt_bind.setJSON([
            {"col1":"A", "col2":"col2_1", "col3":"col3_1", "col4":"col4_1"},
            {"col1":"A", "col2":"col2_2", "col3":"col3_2", "col4":"col4_2"},
            {"col1":"B", "col2":"col2_3", "col3":"col3_3", "col4":"col4_3"},
            {"col1":"B", "col2":"col2_4", "col3":"col3_4", "col4":"col4_4"}
        ], false);
    }

    // con 값을 반영한 headerFilter gridView 동적 생성
    await scwin.createHeaderFilterGridView(vHeaderFilter, vDefaultShow, vMergeCells);
}



// headerFilter 필터 행(filterColumn) 을 포함한 gridView 동적 생성
//  (createBasicGridView 는 filterColumn/headerFilter 구성 불가 → 인라인 구성)
scwin.createHeaderFilterGridView = async function (vHeaderFilter, vDefaultShow, vMergeCells) {
    let grp_comp = $c.gcm.getTestGroup('');
    let ns = $c.gcm.strNameSpace;

    // 미설정('') 속성은 아예 부여하지 않아 기본값(false)으로 동작하도록 함
    let hfAttr = '';
    if (vHeaderFilter === 'true')  hfAttr = ' headerFilter="true"';
    else if (vHeaderFilter === 'false') hfAttr = ' headerFilter="false"';

    let dsAttr = '';
    if (vDefaultShow === 'true')  dsAttr = ' defaultShowHeaderFilter="true"';
    else if (vDefaultShow === 'false') dsAttr = ' defaultShowHeaderFilter="false"';

    let mcAttr = (vMergeCells === 'bycol') ? ' mergeCells="bycol"' : '';

    let s = '';
    s += '<w2:gridView ' + ns + hfAttr + dsAttr + mcAttr + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="defaultShowHeaderFilter 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    // HeaderFilter 필터 행 (filterColumn)
    s += '<w2:row style="" id="rowFilter">';
    s += '<w2:filterColumn width="130" style="" id="filterColumn1" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn2" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn3" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="*" style="" id="filterColumn4" value=""></w2:filterColumn>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 렌더 결과 확인 : defaultShowHeaderFilter 옵션값 + 필터 행 생성/표시 상태 + Body Cell 병합 여부
scwin.btn_checkFilter_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");

    // 대상 속성 옵션값
    let optVal = target1.options.defaultShowHeaderFilter;

    // HeaderFilter 필터 행 (headerFilter=false/미설정 이면 아예 생성되지 않음)
    let filterTr = document.querySelector("[id*='target1_head_table'] tr.w2grid_header_filter");
    let state;
    if (!filterTr) {
        state = '필터행 미생성 (headerFilter=false/미설정 -> HeaderFilter 기능 미생성)';
    } else {
        let shown = filterTr.style.display !== 'none';
        state = '필터행 ' + (shown ? '표시' : '숨김');
    }

    // Body Cell 병합 여부 (mergeCells=bycol 로 col1 세로 병합 시 td[rowspan] 생성)
    let bodyTable = document.querySelector("[id*='target1_body_table']");
    let spanTd = bodyTable ? bodyTable.querySelector("td[rowspan]:not([rowspan='1'])") : null;
    let merged = !!spanTd;

    scb.setReturnValue("defaultShowHeaderFilter 옵션값 : " + optVal + " / " + state + " / Body Cell 병합(td rowspan) : " + (merged ? '있음' : '없음'));
}
